import{_ as t,a,o as d,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Discard","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Discard","query":"curl -X POST \\"https://your-domain.com/api/admin/appearance/themes/default/sections/discard?channel=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{}'\\n","response":"{\\n  \\"themeCode\\": \\"default\\",\\n  \\"channelId\\": 1,\\n  \\"sectionIds\\": [3, 15],\\n  \\"message\\": \\"Section changes discarded successfully.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/sections/discard.md","filePath":"api/rest-api/admin/appearance/sections/discard.md","lastUpdated":1789385991000}`),s={name:"api/rest-api/admin/appearance/sections/discard.md"};function n(o,e,i,h,c,l){return d(),a("div",null,e[0]||(e[0]=[r('<h1 id="discard" tabindex="-1">Discard <a class="header-anchor" href="#discard" aria-label="Permalink to &quot;Discard&quot;">​</a></h1><p>Throws away every staged edit of a theme and channel. The published content, statuses and order are left exactly as they are, so the storefront does not change.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/admin/appearance/themes/{code}/sections/discard</code></td><td>Discard staged section edits</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>Theme whose staged edits are discarded.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>channel</code></td><td>Channel being discarded. Falls back to the current channel.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>themeCode</code></td><td>string</td><td>Theme that was discarded.</td></tr><tr><td><code>channelId</code></td><td>integer</td><td>Channel that was discarded.</td></tr><tr><td><code>sectionIds</code></td><td>array</td><td>Sections whose staged edits were thrown away. Empty when nothing was staged.</td></tr><tr><td><code>message</code></td><td>string</td><td>Confirmation text.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Abandon an edit session</strong> — one call resets every section a merchant touched back to what shoppers already see.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Discarding cannot be undone</strong>, because a staged edit is the only copy of the unpublished work. There is no history to restore it from.</li><li><strong>It does not restore deleted sections.</strong> <a href="/api/rest-api/admin/appearance/sections/delete.html">Delete section</a> is immediate and outside the staging cycle.</li><li><strong>Like publishing, it works per theme and channel</strong> — every section in that pair is reset, not just the one being edited.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>Unknown theme code.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections.edit</code>.</p>',18)]))}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
